

CREATE TABLE `admin` (
  `id` int(5) NOT NULL AUTO_INCREMENT,
  `username` varchar(30) NOT NULL,
  `password` varchar(255) NOT NULL,
  `trans_access` varchar(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=latin1;






CREATE TABLE `buildings` (
  `building_id` int(4) NOT NULL AUTO_INCREMENT,
  `building_num` int(4) DEFAULT NULL,
  `address` varchar(40) NOT NULL,
  `po_box` int(10) DEFAULT NULL,
  `city` varchar(25) NOT NULL,
  `state` varchar(20) NOT NULL,
  `zip_1` int(5) NOT NULL,
  `zip_2` int(4) DEFAULT NULL,
  PRIMARY KEY (`building_id`)
) ENGINE=MyISAM AUTO_INCREMENT=18 DEFAULT CHARSET=latin1;






CREATE TABLE `contact_numbers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `contact_type` varchar(10) NOT NULL,
  `int_prefix` tinyint(1) DEFAULT NULL,
  `prefix` int(3) DEFAULT NULL,
  `first` int(3) DEFAULT NULL,
  `last` int(4) DEFAULT NULL,
  `non_us_number` varchar(25) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=523 DEFAULT CHARSET=latin1;






CREATE TABLE `custom_addresses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `line_1` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `line_2` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `city` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `state` varchar(30) COLLATE utf8_unicode_ci NOT NULL,
  `zip_1` int(5) NOT NULL,
  `zip_2` int(4) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=23 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `custom_instructions` (
  `custom_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `custom_instruction` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`custom_id`)
) ENGINE=MyISAM AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `foreign_choices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `english_w_foreign` int(3) NOT NULL,
  `language` varchar(50) NOT NULL,
  `other_language` varchar(50) NOT NULL,
  `email_language_proof` varchar(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=6 DEFAULT CHARSET=latin1;






CREATE TABLE `manager_instructions` (
  `instruction_id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `instruction_message` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`instruction_id`)
) ENGINE=MyISAM AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `non_us_addresses` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NOT NULL,
  `line_1` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `line_2` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `line_3` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `line_4` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=39 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `notes` (
  `note_id` int(10) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NOT NULL,
  `date_added` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `note_message` varchar(10000) COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`note_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1090 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;






CREATE TABLE `orders` (
  `order_id` int(10) NOT NULL AUTO_INCREMENT,
  `employee_id` varchar(10) COLLATE utf8_unicode_ci NOT NULL,
  `cost_center` int(10) NOT NULL,
  `approved_by` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `delivery_bldg` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `delivery_email` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `ext` int(6) NOT NULL,
  `english_quantity` int(3) DEFAULT NULL,
  `foreign_quantity` int(3) DEFAULT NULL,
  `language` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `other_language` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `foreign_characters_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `foreign_characters_line2` varchar(200) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `foreign_characters_line3` varchar(200) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `foreign_characters_line4` varchar(200) CHARACTER SET utf8 COLLATE utf8_bin DEFAULT NULL,
  `upload_location` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email_language_proof` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `non_us_card` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `full_name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `first_name` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `last_name` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `title` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `title_2` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dept_div` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dept_div_2` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_symbol` varchar(1) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_int_prefix` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_prefix` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_first` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_last` varchar(4) COLLATE utf8_unicode_ci DEFAULT NULL,
  `non_us_phone` varchar(25) COLLATE utf8_unicode_ci DEFAULT NULL,
  `fax_int_prefix` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `fax_prefix` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `fax_first` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `fax_last` varchar(4) COLLATE utf8_unicode_ci DEFAULT NULL,
  `non_us_fax` varchar(25) COLLATE utf8_unicode_ci DEFAULT NULL,
  `additional_contact_exists` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `email` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `mail_stop` int(6) DEFAULT NULL,
  `building_id` int(4) DEFAULT NULL,
  `custom_address` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `no_address` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `notepad_size_425x55` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `notepad_size_55x85` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `shipping_time` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `rush_date` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `comments` mediumtext COLLATE utf8_unicode_ci,
  `custom_proof_requested` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `special_instructions` mediumtext COLLATE utf8_unicode_ci,
  `status` varchar(25) COLLATE utf8_unicode_ci NOT NULL DEFAULT 'waiting_approval',
  `character_hold` varchar(3) COLLATE utf8_unicode_ci DEFAULT NULL,
  `date_submitted` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `date_approved` timestamp NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=814 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

